using FluentAssertions;using Microsoft.AspNetCore.Hosting;using Microsoft.AspNetCore.Mvc.Testing;using Xunit;namespace CGSmartK.IntegrationTests;public class RouteTests:IClassFixture<WebApplicationFactory<Program>>{private readonly HttpClient client;public RouteTests(WebApplicationFactory<Program> factory){client=factory.WithWebHostBuilder(b=>b.UseEnvironment("Development")).CreateClient(new(){AllowAutoRedirect=false});}[Fact]public async Task DashboardIsAvailable(){var response=await client.GetAsync("/");response.IsSuccessStatusCode.Should().BeTrue();}[Fact]public async Task EmployeeCannotOpenAdmin(){var response=await client.GetAsync("/Knowledge");response.StatusCode.Should().Be(System.Net.HttpStatusCode.Forbidden);}[Fact]public async Task AdminCanOpenUpload(){var response=await client.GetAsync("/Knowledge/Upload?as=admin");response.IsSuccessStatusCode.Should().BeTrue();}[Fact]public async Task PostWithoutAntiforgeryIsRejected(){var response=await client.PostAsync("/Chat/Ask",new FormUrlEncodedContent(new Dictionary<string,string>{{"question","Synthetic question"}}));response.StatusCode.Should().Be(System.Net.HttpStatusCode.BadRequest);}}
